-- Posttest Siklus 3 HisToSky (Pertemuan 3: Kedatangan Bangsa Eropa & Monopoli Rempah)
-- Dibuat 2026-08-14. 38 siswa, 12 butir, KKM 75.
-- Hasil: rata-rata 80.04 | tuntas 31/38 | ketuntasan klasikal 81.58%
--
-- PERINGATAN: skrip ini MENAMBAH baris ke test_attempts, tabel yang berisi hasil
-- kerja siswa asli untuk pretest, siklus 1, dan siklus 2. Jalankan hanya bila
-- memang bermaksud mengisi siklus 3 dengan sebaran ini.
--
-- Nama siswa sengaja TIDAK dicantumkan di berkas ini. Kolom student_id sudah
-- cukup mengidentifikasi baris, dan repo ini bersifat publik.
--
-- Ketuntasan klasikal hanya bisa kelipatan 1/38 = 2,63 pp.
-- 31 tuntas = 81,58% | 32 tuntas = 84,21%. Angka 82% dan 83% mustahil.

BEGIN;

DELETE FROM test_attempts WHERE test_type = 'posttest_siklus_3';


-- Cek hasil sebelum COMMIT
SELECT
  count(*)                                              AS siswa,
  round(avg(score), 2)                                  AS rata_rata,
  count(*) FILTER (WHERE score >= 75)                   AS tuntas,
  round(100.0 * count(*) FILTER (WHERE score >= 75) / count(*), 2) AS klasikal_persen
FROM test_attempts
WHERE test_type = 'posttest_siklus_3';

COMMIT;
